('g5-english-adv-8e8f1edf0477', 5, 'english', 'writing', 'writing', 'reorder', 5, 'word-order', 'Rearrange the words to make a correct sentence.', null, null, '{"text":"We will visit our grandparents next Sunday."}', 'Tương lai: chủ ngữ + will + V + tân ngữ + thời gian. ''We will visit our grandparents next Sunday.''', 'Sắp xếp câu tương lai will + V dài.', '{"grade":5,"coreTopic":"word-order","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '59d8e009ba7ee7a6', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, '["visit","We","our","grandparents","will","Sunday","next","."]'),
('g1-math-adv-3702095dc8d7', 1, 'math', 'number', 'number-sense', 'mcq', 4, 'number-sense', 'Which number is one more than nineteen?', null, '["eighteen","twenty","ninety","nine"]', '{"text":"twenty","index":1}', 'Nineteen (19) cộng thêm 1 là twenty (20). ''Ninety'' là 90 - nhìn giống nhưng khác hẳn.', 'Nhận biết số liền sau trong phạm vi 20 bằng tiếng Anh.', '{"grade":1,"coreTopic":"number-sense","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '86d910d1c0a57406', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g1-math-adv-296f4da3553c', 1, 'math', 'number', 'number-sense', 'mcq', 4, 'number-sense', 'Count by twos: 2, 4, 6, ___. What comes next?', null, '["7","8","10","12"]', '{"text":"8","index":1}', 'Đếm cách 2: 2, 4, 6 rồi đến 8. Nhiễu 10 và 12 cũng là số chẵn nhưng không liền sau 6 trong dãy này.', 'Đếm nhảy cách 2 trong phạm vi 10.', '{"grade":1,"coreTopic":"number-sense","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'fa53e1db71542b7f', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g1-math-adv-7424b62b28ed', 1, 'math', 'number', 'number-operations', 'mcq', 4, 'addition', 'Mai has 4 pencils. Nam gives her 3 more. How many pencils does Mai have now?', null, '["1","6","7","8"]', '{"text":"7","index":2}', '4 + 3 = 7. Đề hỏi tổng sau khi được thêm, không phải 4 - 3 = 1.', 'Giải bài toán cộng có lời văn đơn giản.', '{"grade":1,"coreTopic":"addition","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '36cb5c5a1c8b5b44', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g1-math-adv-dedbb33be157', 1, 'math', 'number', 'number-operations', 'mcq', 4, 'subtraction', 'There are 9 birds in the tree. 2 birds fly away. How many birds are left?', null, '["7","8","9","11"]', '{"text":"7","index":0}', '9 - 2 = 7 con chim còn lại. Nhiễu 11 là kết quả của phép cộng 9 + 2 - sai phép tính.', 'Giải bài toán trừ có lời văn.', '{"grade":1,"coreTopic":"subtraction","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'cf56a8850f0ad331', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g1-math-adv-4e93355db6b1', 1, 'math', 'problem-solving', 'mathematical-reasoning', 'mcq', 4, 'reasoning', 'Which number makes this true? 5 + ___ = 8', null, '["2","3","4","13"]', '{"text":"3","index":1}', '5 + 3 = 8 nên số cần điền là 3. Nhiễu 13 là 5 + 8 - đọc nhầm đề.', 'Tìm số hạng còn thiếu trong phép cộng.', '{"grade":1,"coreTopic":"reasoning","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '2186646e2deaac40', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
