('g3-math-adv-a7f4a95eeef4', 3, 'math', 'number', 'number-operations', 'mcq', 4, 'division', 'What is 56 ÷ 8?', null, '["6","7","8","9"]', '{"text":"7","index":1}', '56 ÷ 8 = 7 vì 7 x 8 = 56. Chia là phép ngược của nhân.', 'Chia trong phạm vi bảng nhân 8.', '{"grade":3,"coreTopic":"division","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'a9cd15eebfd4ed12', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g3-math-adv-a22b770d5979', 3, 'math', 'problem-solving', 'problem-solving', 'mcq', 4, 'word-problems', 'A pack has 8 crayons. Teacher buys 6 packs for the class. How many crayons are there in all?', null, '["14","42","48","68"]', '{"text":"48","index":2}', '8 x 6 = 48 bút màu. Nhiễu 14 là 8+6; 68 ghép hai số - đều sai.', 'Nhân có lời văn một bước.', '{"grade":3,"coreTopic":"word-problems","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'eb32fba90310bb80', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g3-math-adv-46a4b736629b', 3, 'math', 'problem-solving', 'problem-solving', 'mcq', 4, 'word-problems', 'Huy has 45 stickers. He puts them equally into 5 albums. How many stickers are in each album?', null, '["8","9","40","50"]', '{"text":"9","index":1}', '45 ÷ 5 = 9 sticker mỗi album. Chia đều = phép chia.', 'Chia đều có lời văn.', '{"grade":3,"coreTopic":"word-problems","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '891438c54e93f718', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g3-math-adv-1fc26bffcdfa', 3, 'math', 'number', 'fractions', 'mcq', 4, 'fractions', 'A pizza is cut into 8 equal slices. Tuan eats 3 slices. What fraction of the pizza does he eat?', null, '["3/5","3/8","5/8","8/3"]', '{"text":"3/8","index":1}', 'Ăn 3 trong 8 phần bằng nhau = 3/8. Nhiễu 5/8 là phần còn lại - đọc kỹ đề hỏi phần ĐÃ ăn.', 'Đọc phân số từ tình huống chia phần bằng nhau.', '{"grade":3,"coreTopic":"fractions","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '77a5777de0bce6ba', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g3-math-adv-e00ab48c4c0c', 3, 'math', 'problem-solving', 'mathematical-reasoning', 'mcq', 4, 'patterns', 'Look at the pattern: 3, 6, 11, 18, 27, ___. What comes next?', null, '["36","37","38","39"]', '{"text":"38","index":2}', 'Khoảng cách tăng dần: +3, +5, +7, +9 nên tiếp là +11: 27 + 11 = 38.', 'Nhận diện dãy số có khoảng cách tăng dần.', '{"grade":3,"coreTopic":"patterns","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'ee65851ffc3ccf34', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g3-math-adv-8bf127561aa9', 3, 'math', 'measurement', 'measurement', 'mcq', 4, 'time', 'A film starts at 2:30 and lasts 90 minutes. What time does it end?', null, '["3:30","4:00","4:30","5:00"]', '{"text":"4:00","index":1}', '90 phút = 1 giờ 30 phút. 2:30 + 1:30 = 4:00. Nhiễu 4:30 cộng nhầm 2 giờ.', 'Cộng thời gian vượt qua giờ chẵn.', '{"grade":3,"coreTopic":"time","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '4f952325acc346d5', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g3-math-adv-1523d8e1442f', 3, 'math', 'number', 'number-sense', 'mcq', 4, 'place-value', 'What is the value of digit 7 in the number 472?', null, '["7","70","700","7000"]', '{"text":"70","index":1}', 'Chữ số 7 ở hàng chục = 70. 472 = 400 + 70 + 2.', 'Giá trị chữ số theo hàng trong số có 3 chữ số.', '{"grade":3,"coreTopic":"place-value","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '358c8b10b34afa53', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g3-math-adv-8190345bd844', 3, 'math', 'problem-solving', 'problem-solving', 'mcq', 4, 'word-problems', 'A farmer has 36 eggs. He sells 15 in the morning and 12 in the afternoon. How many eggs are left?', null, '["9","21","24","63"]', '{"text":"9","index":0}', 'Bán tổng 15 + 12 = 27 quả; còn 36 - 27 = 9. Bài toán 2 bước: cộng rồi trừ.', 'Giải bài toán hai bước cộng-trừ.', '{"grade":3,"coreTopic":"word-problems","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'dc8ccd3722ae5c04', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g3-math-adv-147ad2158aab', 3, 'math', 'problem-solving', 'mathematical-reasoning', 'mcq', 4, 'reasoning', 'Which number makes this true? 8 x ___ = 96', null, '["10","11","12","14"]', '{"text":"12","index":2}', '96 ÷ 8 = 12 nên số cần điền là 12. Kiểm tra: 8 x 12 = 96.', 'Tìm thừa số còn thiếu bằng phép chia.', '{"grade":3,"coreTopic":"reasoning","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '6f4eba0b76ee0e40', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g3-math-adv-ab518aea0203', 3, 'math', 'geometry', 'geometry', 'mcq', 4, 'shapes', 'How many corners (vertices) does a cube have?', null, '["4","6","8","12"]', '{"text":"8","index":2}', 'Khối lập phương có 8 đỉnh (4 đỉnh mặt trên + 4 đỉnh mặt dưới). Nhiễu 6 là số mặt; 12 là số cạnh.', 'Đếm đỉnh của khối lập phương.', '{"grade":3,"coreTopic":"shapes","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'c4db265c592b1480', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g3-math-adv-36576f5e64eb', 3, 'math', 'data', 'data', 'mcq', 4, 'graphs', 'A picture graph shows: Monday = 4 apples, Tuesday = 6 apples, Wednesday = 2 apples. On which day were the FEWEST apples sold?', null, '["Monday","Tuesday","Wednesday","All equal"]', '{"text":"Wednesday","index":2}', 'Wednesday chỉ 2 quả - ít nhất. Đề hỏi ÍT nhất, không phải nhiều nhất (Tuesday).', 'Đọc và so sánh dữ liệu từ biểu đồ tranh.', '{"grade":3,"coreTopic":"graphs","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'ecba60109526e3fc', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g3-math-adv-5df6e0f6c728', 3, 'math', 'problem-solving', 'problem-solving', 'mcq', 5, 'word-problems', 'Each box holds 9 cakes. There are 52 cakes. How many boxes are needed to pack ALL the cakes?', null, '["5","6","7","8"]', '{"text":"6","index":1}', '52 ÷ 9 = 5 dư 7. Còn dư 7 cái vẫn cần 1 hộp nữa: 5 + 1 = 6 hộp. Bẫy kinh điển của chia có dư.', 'Chia có dư và làm tròn lên theo ngữ cảnh.', '{"grade":3,"coreTopic":"word-problems","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'eb1a51c99516cd4a', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g3-math-adv-4bdb9094e73e', 3, 'math', 'number', 'number-operations', 'mcq', 5, 'mixed', 'What is 6 x 7 + 8?', null, '["42","50","56","90"]', '{"text":"50","index":1}', 'Nhân trước cộng sau: 6 x 7 = 42, rồi 42 + 8 = 50.', 'Thứ tự phép tính nhân trước cộng sau.', '{"grade":3,"coreTopic":"mixed","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'ace3fd8562b56e8d', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g4-math-adv-586710753089', 4, 'math', 'number', 'number-operations', 'mcq', 4, 'multiplication', 'What is 25 x 14?', null, '["300","325","350","375"]', '{"text":"350","index":2}', 'Tách để nhân nhanh: 25 x 14 = 25 x 10 + 25 x 4 = 250 + 100 = 350.', 'Nhân số hai chữ số bằng tách số.', '{"grade":4,"coreTopic":"multiplication","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '75f78dd853d148d4', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
